-- ELECTRA INDEX — INSTALL_APPS_FR : French descriptions for the 48 AI apps (2 Nov 2026) + public read view
-- Paste everything in Supabase > SQL Editor > Run. Re-runnable.

create or replace view v_app_i18n as
select e.slug, t.lang, t.value as short_description,
       (t.source_text is distinct from e.short_description) as stale, t.updated_at
  from entity_i18n t join entities e on e.id = t.entity_id
 where e.type = 'app' and e.is_published and t.field = 'short_description';
grant select on v_app_i18n to anon, authenticated;

select i18n_set('app', (select slug from entities where type = 'app' and name = 'Speeko' and is_published limit 1), 'fr', 'short_description', 'App de coaching en prise de parole qui analyse vos discours enregistrés avec l''IA et propose des jeux de rôle conversationnels pour s''entraîner.', 'Public speaking coach app that gives AI feedback on recorded speech and offers AI roleplay conversations for practice.');
