select i18n_set('app', (select slug from entities where type = 'app' and name = 'Vocal Image' and is_published limit 1), 'fr', 'short_description', 'App de coaching de la voix et de la communication avec évaluation vocale par IA et leçons pour parler clairement et avec assurance.', 'Voice and communication coaching app with AI voice evaluation and lessons for speaking clearly and confidently.');
