select i18n_set('app', (select slug from entities where type = 'app' and name = 'Suno' and is_published limit 1), 'fr', 'short_description', 'Générateur de musique IA qui crée des chansons avec voix et instruments à partir d''un texte ou de paroles.', 'AI music generator that creates songs with vocals and instrumentals from text prompts or lyrics.');
